const item = $input.first();
const headers = item.json.headers || {};
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = buf.toString('utf8');
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
return [{ json: { rawBody, timestamp, signature, signedString: `${timestamp}.${rawBody}` } }];

const j = $input.first().json;
const sig = String(j.signature).replace(/^sha256=/, '');
const exp = String(j.expected);
// constant-time compare
let diff = sig.length ^ exp.length;
for (let i = 0; i < Math.min(sig.length, exp.length); i++) {
  diff |= sig.charCodeAt(i) ^ exp.charCodeAt(i);
}
const ts = Number(j.timestamp);
const fresh = Number.isFinite(ts) && Math.abs(Date.now() - ts) <= 5 * 60 * 1000;
let payload = null;
try { payload = JSON.parse(j.rawBody); } catch (e) {}
const valid = diff === 0 && fresh && payload !== null;
return [{ json: valid ? { valid, ...payload } : { valid: false } }];

const e = $input.first().json;
const tool = e.toolName;
const dates = `${e.startDate} to ${e.endDate}`;
let subject = '';
let text = '';

if (e.type === 'request.created') {
  subject = `New borrow request for ${tool}`;
  text = `${e.otherPartyName} wants to borrow your ${tool} (${dates}).`;
} else if (e.type === 'loan.returned') {
  subject = `${tool} marked as returned`;
  text = `${e.otherPartyName} confirmed that ${tool} was returned. Thanks!`;
} else if (e.status === 'approved') {
  subject = `Request approved: ${tool}`;
  text = `${e.otherPartyName} approved your request for ${tool} (${dates}).`;
} else if (e.status === 'declined') {
  subject = `Request declined: ${tool}`;
  text = `${e.otherPartyName} declined your request for ${tool}.`;
} else if (e.status === 'cancelled') {
  subject = `Request cancelled: ${tool}`;
  text = `${e.otherPartyName} cancelled their request for ${tool}.`;
} else {
  throw new Error(`Unknown event: ${e.type}/${e.status}`);
}

// MOCK notification (visible in the execution view).
// Replace this node with Email / Slack / Discord later.
return [{ json: { channel: 'mock', to: e.recipient.email, name: e.recipient.name, subject, text, eventId: e.eventId } }];
